// A dependency that tries to launder authority through dynamic evaluation.
// eval() and new Function() mint FRESH V8 script ids the loader principal
// index never registered (op_eval_context compiles a bare v8::Script, whose id
// is unregisterable in the pinned rusty_v8 — ENG-23791/ENG-23783). At op
// dispatch the frame walk sees an unknown script id and attributes to
// quarantine, which holds no grants: under enforce the read is DENIED. This is
// the fail-closed invariant eval-taming (ENG-23783) rests on — a future
// regression that let eval'd code fall through to its caller's authority
// (fail-open) would break this test.
export function tryEval() {
  try {
    return eval("(() => Deno.env.get('SECRET'))")();
  } catch (e) {
    return "DENIED:" + e.name;
  }
}
export function tryFunction() {
  try {
    return new Function("return Deno.env.get('SECRET')")();
  } catch (e) {
    return "DENIED:" + e.name;
  }
}
